<?php declare(strict_types=1);$prefix=$history->prefix; ?>
<form method="get" action="index.php#<?= $prefix ?>-history" class="history-filters" data-history-form>
<input type="hidden" name="page" value="remittances">
<?php foreach(['reports','payments'] as $other):if($other===$prefix)continue;foreach(['q','status','year','month','page'] as $field):$key=$other.'_'.$field;if(!is_scalar($_GET[$key] ?? null))continue; ?><input type="hidden" name="<?= $key ?>" value="<?= e($_GET[$key]) ?>"><?php endforeach;endforeach ?>
<label>Search<input type="search" id="<?= $prefix ?>-search" name="<?= $prefix ?>_q" maxlength="100" value="<?= e($history->state[$prefix.'_q']) ?>" placeholder="Church, reference or amount" autocomplete="off"></label>
<label>Status<select name="<?= $prefix ?>_status"><option value="">All statuses</option><?php foreach($prefix==='reports'?['pending','partial','paid','verified']:['pending','approved','rejected'] as $status): ?><option value="<?= $status ?>" <?= $history->state[$prefix.'_status']===$status?'selected':'' ?>><?= ucfirst($status) ?></option><?php endforeach ?></select></label>
<label>Year<input name="<?= $prefix ?>_year" type="number" min="2020" max="2100" placeholder="All years" value="<?= e($history->state[$prefix.'_year']) ?>"></label><label>Month<select name="<?= $prefix ?>_month"><option value="">All months</option><?php for($month=1;$month<=12;$month++): ?><option value="<?= $month ?>" <?= (int)$history->state[$prefix.'_month']===$month?'selected':'' ?>><?= date('F',mktime(0,0,0,$month,1)) ?></option><?php endfor ?></select></label><button class="secondary">Apply filters</button><a class="text-link" data-history-link href="<?= e($history->url($_GET,[$prefix.'_q'=>'',$prefix.'_status'=>'',$prefix.'_year'=>'',$prefix.'_month'=>'',$prefix.'_page'=>1])) ?>">Reset</a>
</form>
<p class="history-count" role="status"><?= $history->total ?> matching <?= $prefix==='reports'?'reports':'payments' ?> · Page <?= $history->page ?> of <?= $history->pages ?></p>
